export const templates: readonly EmbeddedSpec[] = [
  { name: "lesson-blue-green", title: "Lesson: blue-green deployment", description: "Two identical environments: deploy to the idle one, test it, then switch the load balancer. Rolling back is switching again.", json: "{\n  \"$schema\": \"https://platformcosmo.io/schema/v1.json\",\n  \"meta\": {\n    \"version\": \"1\",\n    \"title\": \"Lesson: blue-green deployment\",\n    \"description\": \"Two identical environments: deploy to the idle one, test it, then switch the load balancer. Rolling back is switching again.\"\n  },\n  \"canvas\": { \"theme\": \"light\" },\n  \"nodes\": [\n    { \"id\": \"users\", \"type\": \"users\", \"label\": \"Users\" },\n    { \"id\": \"lb\", \"type\": \"lb\", \"label\": \"Load balancer\" },\n    { \"id\": \"blue\", \"type\": \"server\", \"label\": \"Blue (v1)\", \"group\": \"envs\" },\n    { \"id\": \"green\", \"type\": \"server\", \"label\": \"Green (v2)\", \"group\": \"envs\" },\n    { \"id\": \"pipeline\", \"type\": \"pipeline\", \"label\": \"Release pipeline\" }\n  ],\n  \"groups\": [{ \"id\": \"envs\", \"label\": \"Environments\", \"style\": \"cluster\" }],\n  \"edges\": [\n    { \"id\": \"users-lb\", \"from\": \"users\", \"to\": \"lb\" },\n    { \"id\": \"lb-blue\", \"from\": \"lb\", \"to\": \"blue\" },\n    { \"id\": \"lb-green\", \"from\": \"lb\", \"to\": \"green\", \"style\": \"dashed\" },\n    { \"id\": \"pipeline-green\", \"from\": \"pipeline\", \"to\": \"green\", \"style\": \"dotted\" }\n  ],\n  \"steps\": [\n    {\n      \"caption\": \"1. Blue serves all traffic\",\n      \"flows\": [\n        { \"edge\": \"users-lb\", \"kind\": \"heavy\" },\n        { \"edge\": \"lb-blue\", \"kind\": \"heavy\" }\n      ],\n      \"set\": { \"blue\": \"highlighted\" }\n    },\n    {\n      \"caption\": \"2. The pipeline deploys v2 to Green while Blue keeps serving\",\n      \"flows\": [\n        { \"edge\": \"users-lb\" },\n        { \"edge\": \"lb-blue\" },\n        { \"edge\": \"pipeline-green\", \"kind\": \"heavy\" }\n      ],\n      \"set\": { \"blue\": \"healthy\", \"green\": \"degraded\" }\n    },\n    {\n      \"caption\": \"3. Green passes its health checks\",\n      \"flows\": [\n        { \"edge\": \"lb-green\", \"kind\": \"health\" },\n        { \"edge\": \"users-lb\" },\n        { \"edge\": \"lb-blue\" }\n      ],\n      \"set\": { \"green\": \"healthy\" }\n    },\n    {\n      \"caption\": \"4. The load balancer switches; Blue stays warm for instant rollback\",\n      \"flows\": [\n        { \"edge\": \"users-lb\", \"kind\": \"heavy\" },\n        { \"edge\": \"lb-green\", \"kind\": \"heavy\" }\n      ],\n      \"set\": { \"green\": \"highlighted\", \"blue\": \"healthy\" }\n    }\n  ]\n}\n" },
  { name: "lesson-cache-aside", title: "Lesson: the cache-aside pattern", description: "The app checks the cache first, falls back to the database on a miss, and fills the cache so the next read is fast.", json: "{\n  \"$schema\": \"https://platformcosmo.io/schema/v1.json\",\n  \"meta\": {\n    \"version\": \"1\",\n    \"title\": \"Lesson: the cache-aside pattern\",\n    \"description\": \"The app checks the cache first, falls back to the database on a miss, and fills the cache so the next read is fast.\"\n  },\n  \"canvas\": { \"theme\": \"light\" },\n  \"nodes\": [\n    { \"id\": \"client\", \"type\": \"client\", \"label\": \"Client\" },\n    { \"id\": \"app\", \"type\": \"server\", \"label\": \"App\" },\n    { \"id\": \"cache\", \"type\": \"cache\", \"label\": \"Cache\" },\n    { \"id\": \"db\", \"type\": \"sql\", \"label\": \"Database\" }\n  ],\n  \"edges\": [\n    { \"id\": \"client-app\", \"from\": \"client\", \"to\": \"app\" },\n    { \"id\": \"app-cache\", \"from\": \"app\", \"to\": \"cache\" },\n    { \"id\": \"app-db\", \"from\": \"app\", \"to\": \"db\", \"style\": \"dashed\" }\n  ],\n  \"metrics\": [\n    { \"id\": \"latency\", \"label\": \"Read latency\", \"value\": \"-\" },\n    { \"id\": \"hit-rate\", \"label\": \"Cache hit rate\", \"value\": \"0%\" }\n  ],\n  \"steps\": [\n    {\n      \"caption\": \"1. A read arrives; the app asks the cache first\",\n      \"flows\": [{ \"edge\": \"client-app\" }, { \"edge\": \"app-cache\" }],\n      \"set\": { \"cache\": \"highlighted\" }\n    },\n    {\n      \"caption\": \"2. Miss: the cache has nothing, so the app reads the database\",\n      \"flows\": [{ \"edge\": \"app-db\", \"kind\": \"heavy\" }],\n      \"set\": { \"cache\": \"degraded\", \"db\": \"highlighted\" },\n      \"metrics\": { \"latency\": \"48 ms\", \"hit-rate\": \"0%\" }\n    },\n    {\n      \"caption\": \"3. The app stores the result in the cache for next time\",\n      \"flows\": [{ \"edge\": \"app-cache\", \"kind\": \"heavy\" }],\n      \"set\": { \"cache\": \"healthy\", \"db\": \"healthy\" }\n    },\n    {\n      \"caption\": \"4. The next read is a hit and skips the database\",\n      \"flows\": [{ \"edge\": \"client-app\" }, { \"edge\": \"app-cache\" }],\n      \"set\": { \"cache\": \"highlighted\" },\n      \"metrics\": { \"latency\": \"2 ms\", \"hit-rate\": \"90%\" }\n    }\n  ]\n}\n" },
  { name: "lesson-circuit-breaker", title: "Lesson: circuit breaker and fallback", description: "A gateway stops calling a failing service after repeated errors and serves a fallback instead, protecting the rest of the system.", json: "{\n  \"$schema\": \"https://platformcosmo.io/schema/v1.json\",\n  \"meta\": {\n    \"version\": \"1\",\n    \"title\": \"Lesson: circuit breaker and fallback\",\n    \"description\": \"A gateway stops calling a failing service after repeated errors and serves a fallback instead, protecting the rest of the system.\"\n  },\n  \"canvas\": { \"theme\": \"light\" },\n  \"nodes\": [\n    { \"id\": \"client\", \"type\": \"client\", \"label\": \"Client\" },\n    { \"id\": \"gateway\", \"type\": \"gateway\", \"label\": \"Gateway\", \"badge\": \"circuit breaker\" },\n    { \"id\": \"orders\", \"type\": \"server\", \"label\": \"Orders service\" },\n    { \"id\": \"fallback\", \"type\": \"cache\", \"label\": \"Fallback cache\" }\n  ],\n  \"edges\": [\n    { \"id\": \"client-gateway\", \"from\": \"client\", \"to\": \"gateway\" },\n    { \"id\": \"gateway-orders\", \"from\": \"gateway\", \"to\": \"orders\" },\n    { \"id\": \"gateway-fallback\", \"from\": \"gateway\", \"to\": \"fallback\", \"style\": \"dashed\" }\n  ],\n  \"metrics\": [{ \"id\": \"errors\", \"label\": \"Error rate\", \"value\": \"0%\" }],\n  \"steps\": [\n    {\n      \"caption\": \"1. Closed: requests flow to the Orders service\",\n      \"flows\": [{ \"edge\": \"client-gateway\" }, { \"edge\": \"gateway-orders\" }]\n    },\n    {\n      \"caption\": \"2. Orders starts failing and errors pile up\",\n      \"set\": { \"orders\": \"degraded\" },\n      \"flows\": [{ \"edge\": \"gateway-orders\", \"kind\": \"failed\" }],\n      \"metrics\": { \"errors\": \"40%\" }\n    },\n    {\n      \"caption\": \"3. Open: the breaker trips and stops calling Orders\",\n      \"set\": { \"orders\": \"down\", \"gateway\": \"highlighted\" },\n      \"flows\": [{ \"edge\": \"client-gateway\" }],\n      \"metrics\": { \"errors\": \"40%\" }\n    },\n    {\n      \"caption\": \"4. The gateway serves a fallback instead of failing\",\n      \"set\": { \"fallback\": \"highlighted\" },\n      \"flows\": [{ \"edge\": \"client-gateway\" }, { \"edge\": \"gateway-fallback\", \"kind\": \"heavy\" }],\n      \"metrics\": { \"errors\": \"0%\" }\n    },\n    {\n      \"caption\": \"5. Half-open: a probe checks whether Orders has recovered\",\n      \"set\": { \"orders\": \"degraded\", \"fallback\": \"healthy\", \"gateway\": \"healthy\" },\n      \"flows\": [{ \"edge\": \"gateway-orders\", \"kind\": \"health\" }]\n    },\n    {\n      \"caption\": \"6. The probe succeeds: the breaker closes and Orders serves traffic again\",\n      \"set\": { \"orders\": \"healthy\" },\n      \"flows\": [{ \"edge\": \"client-gateway\" }, { \"edge\": \"gateway-orders\" }],\n      \"metrics\": { \"errors\": \"0%\" }\n    }\n  ]\n}\n" },
  { name: "lesson-rag-basics", title: "Lesson: retrieval-augmented generation", description: "Two phases: ingest documents into a vector database, then answer questions by retrieving context for the model.", json: "{\n  \"$schema\": \"https://platformcosmo.io/schema/v1.json\",\n  \"meta\": {\n    \"version\": \"1\",\n    \"title\": \"Lesson: retrieval-augmented generation\",\n    \"description\": \"Two phases: ingest documents into a vector database, then answer questions by retrieving context for the model.\"\n  },\n  \"canvas\": { \"theme\": \"light\" },\n  \"nodes\": [\n    { \"id\": \"docs\", \"type\": \"object-store\", \"label\": \"Documents\", \"group\": \"ingest\" },\n    { \"id\": \"embed-ingest\", \"type\": \"embedding\", \"label\": \"Embedder\", \"group\": \"ingest\" },\n    { \"id\": \"vectors\", \"type\": \"vector-db\", \"label\": \"Vector DB\" },\n    { \"id\": \"user\", \"type\": \"client\", \"label\": \"User\", \"group\": \"query\" },\n    { \"id\": \"retriever\", \"type\": \"rag\", \"label\": \"Retriever\", \"group\": \"query\" },\n    { \"id\": \"llm\", \"type\": \"llm\", \"label\": \"LLM\", \"group\": \"query\" }\n  ],\n  \"groups\": [\n    { \"id\": \"ingest\", \"label\": \"Ingest (offline)\", \"style\": \"zone\" },\n    { \"id\": \"query\", \"label\": \"Query (online)\", \"style\": \"platform\" }\n  ],\n  \"edges\": [\n    { \"id\": \"docs-embed\", \"from\": \"docs\", \"to\": \"embed-ingest\" },\n    { \"id\": \"embed-vectors\", \"from\": \"embed-ingest\", \"to\": \"vectors\" },\n    { \"id\": \"user-retriever\", \"from\": \"user\", \"to\": \"retriever\" },\n    { \"id\": \"retriever-vectors\", \"from\": \"retriever\", \"to\": \"vectors\" },\n    { \"id\": \"retriever-llm\", \"from\": \"retriever\", \"to\": \"llm\" }\n  ],\n  \"steps\": [\n    {\n      \"caption\": \"Ingest: documents are split, embedded and stored as vectors\",\n      \"flows\": [{ \"edge\": \"docs-embed\" }, { \"edge\": \"embed-vectors\", \"kind\": \"heavy\" }],\n      \"set\": { \"vectors\": \"highlighted\" }\n    },\n    {\n      \"caption\": \"Query: the question reaches the retriever\",\n      \"flows\": [{ \"edge\": \"user-retriever\" }],\n      \"set\": { \"vectors\": \"healthy\", \"retriever\": \"highlighted\" }\n    },\n    {\n      \"caption\": \"The retriever finds the most similar chunks\",\n      \"flows\": [{ \"edge\": \"retriever-vectors\", \"kind\": \"heavy\" }],\n      \"set\": { \"vectors\": \"highlighted\" }\n    },\n    {\n      \"caption\": \"The LLM answers using the question plus the retrieved chunks\",\n      \"flows\": [{ \"edge\": \"retriever-llm\", \"kind\": \"heavy\" }],\n      \"set\": { \"vectors\": \"healthy\", \"llm\": \"highlighted\" }\n    }\n  ]\n}\n" },
  { name: "lesson-request-lifecycle", title: "Lesson: life of a web request", description: "Follow one request from the browser through DNS, CDN, load balancer and app to the database and back. Edit the labels and captions to teach your own stack.", json: "{\n  \"$schema\": \"https://platformcosmo.io/schema/v1.json\",\n  \"meta\": {\n    \"version\": \"1\",\n    \"title\": \"Lesson: life of a web request\",\n    \"description\": \"Follow one request from the browser through DNS, CDN, load balancer and app to the database and back. Edit the labels and captions to teach your own stack.\"\n  },\n  \"canvas\": { \"theme\": \"light\" },\n  \"nodes\": [\n    { \"id\": \"browser\", \"type\": \"client\", \"label\": \"Browser\" },\n    { \"id\": \"dns\", \"type\": \"dns\", \"label\": \"DNS\" },\n    { \"id\": \"cdn\", \"type\": \"cdn\", \"label\": \"CDN\" },\n    { \"id\": \"lb\", \"type\": \"lb\", \"label\": \"Load balancer\" },\n    { \"id\": \"app\", \"type\": \"server\", \"label\": \"App server\" },\n    { \"id\": \"db\", \"type\": \"sql\", \"label\": \"Database\" }\n  ],\n  \"edges\": [\n    { \"id\": \"browser-dns\", \"from\": \"browser\", \"to\": \"dns\", \"style\": \"dotted\" },\n    { \"id\": \"browser-cdn\", \"from\": \"browser\", \"to\": \"cdn\" },\n    { \"id\": \"cdn-lb\", \"from\": \"cdn\", \"to\": \"lb\" },\n    { \"id\": \"lb-app\", \"from\": \"lb\", \"to\": \"app\" },\n    { \"id\": \"app-db\", \"from\": \"app\", \"to\": \"db\" }\n  ],\n  \"steps\": [\n    {\n      \"caption\": \"1. The browser asks DNS where the site lives\",\n      \"set\": { \"dns\": \"highlighted\" },\n      \"flows\": [{ \"edge\": \"browser-dns\", \"kind\": \"health\" }]\n    },\n    {\n      \"caption\": \"2. It sends the request to the nearest CDN edge\",\n      \"set\": { \"dns\": \"healthy\", \"cdn\": \"highlighted\" },\n      \"flows\": [{ \"edge\": \"browser-cdn\" }]\n    },\n    {\n      \"caption\": \"3. A cache miss goes to the origin through the load balancer\",\n      \"set\": { \"cdn\": \"healthy\", \"lb\": \"highlighted\" },\n      \"flows\": [{ \"edge\": \"cdn-lb\" }, { \"edge\": \"lb-app\" }]\n    },\n    {\n      \"caption\": \"4. The app reads from the database and the response travels back\",\n      \"set\": { \"lb\": \"healthy\", \"app\": \"highlighted\", \"db\": \"highlighted\" },\n      \"flows\": [{ \"edge\": \"app-db\", \"kind\": \"heavy\" }]\n    }\n  ]\n}\n" },
  { name: "starter", title: "My architecture", description: "Starter: users reach a web server that reads from a database. Edit the nodes, then run pcosmo build.", json: "{\n  \"$schema\": \"https://platformcosmo.io/schema/v1.json\",\n  \"meta\": {\n    \"version\": \"1\",\n    \"title\": \"My architecture\",\n    \"description\": \"Starter: users reach a web server that reads from a database. Edit the nodes, then run pcosmo build.\"\n  },\n  \"nodes\": [\n    { \"id\": \"users\", \"type\": \"users\", \"label\": \"Users\" },\n    { \"id\": \"web\", \"type\": \"server\", \"label\": \"Web server\" },\n    { \"id\": \"db\", \"type\": \"sql\", \"label\": \"Database\" }\n  ],\n  \"edges\": [\n    { \"id\": \"users-web\", \"from\": \"users\", \"to\": \"web\" },\n    { \"id\": \"web-db\", \"from\": \"web\", \"to\": \"db\" }\n  ],\n  \"flows\": [{ \"edge\": \"users-web\" }, { \"edge\": \"web-db\" }]\n}\n" },
];
